<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorMessage,download} from '../api/http'
import {ElMessage} from 'element-plus'
const props=defineProps<{mode:'sales'|'monitor'}>(),route=useRoute(),router=useRouter(),data=ref<any>(null),busy=ref(false),error=ref('')
const record=computed(()=>data.value?.record||{}),source=computed(()=>record.value.source_data||{})
async function load(){busy.value=true;error.value='';try{data.value=await api<any>('/deadlines/'+route.params.id)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function file(a:any){try{await download('/imports/deadlines/'+a.import_id+'/file',a.file_name)}catch(e){ElMessage.error(errorMessage(e))}}
onMounted(load)
</script>
<template><h1 class="page-title">{{mode==='sales'?'受注詳細（契約情報）':'監視詳細'}}</h1>
<div class="actions" style="margin-bottom:18px"><el-button @click="router.push(mode==='sales'?'/sales':'/monitor')">一覧へ</el-button><el-button v-if="data" type="primary" plain @click="router.push(mode==='sales'?'/monitor/'+route.params.id:'/sales/contracts/'+route.params.id)">{{mode==='sales'?'5年間監視の詳細へ':'販売管理の詳細へ'}}</el-button></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-loading="busy">
<template v-if="data"><div class="banner">同じ契約・設備・許可記録を両画面で参照しています。監視状況と次回確認日は要確認です。年度の原文に完了日があっても、確認済みの業務状態には自動変更しません。</div>
<section class="panel"><header class="panel-heading">基本情報・関連輸出情報</header><div class="panel-body"><el-descriptions :column="2" border>
<el-descriptions-item label="契約番号">{{record.contract_no}}</el-descriptions-item><el-descriptions-item label="商品名">{{record.product_name||'未記載'}}</el-descriptions-item><el-descriptions-item label="型番">{{record.model_no||'未記載'}}</el-descriptions-item><el-descriptions-item label="監視状況">要確認</el-descriptions-item>
<el-descriptions-item label="輸出許可番号">{{record.export_permit_no||'未記載'}}</el-descriptions-item><el-descriptions-item label="役務許可番号">{{record.service_permit_no||'未記載'}}</el-descriptions-item><el-descriptions-item label="経済産業省輸出許可日">{{record.permit_date||'要確認'}}</el-descriptions-item><el-descriptions-item label="有効期限">{{record.valid_until||'要確認'}}</el-descriptions-item>
<el-descriptions-item label="担当者">{{record.person_in_charge||'未記載'}}</el-descriptions-item><el-descriptions-item label="責任者">{{record.responsible_person||'未記載'}}</el-descriptions-item></el-descriptions><p class="data-note">顧客・売上金額・受注日は元資料にないため未登録です。</p></div></section>
<section class="panel"><header class="panel-heading">期限管理</header><div class="panel-body"><el-descriptions :column="2" border><el-descriptions-item label="貨物輸入後設置日（原票の予定日）">{{record.installation_date||'未記載／要確認'}}</el-descriptions-item><el-descriptions-item label="設置完了報告提出期限">{{record.report_due_date||'要確認'}}</el-descriptions-item><el-descriptions-item label="貨物B/L日付">{{record.bl_date||'未記載／要確認'}}</el-descriptions-item><el-descriptions-item label="次回確認日">要確認（自動計算なし）</el-descriptions-item></el-descriptions></div></section>
<section class="panel"><header class="panel-heading">五年監視記録</header><div class="panel-body"><el-table :data="data.years" border><el-table-column label="年度" width="85"><template #default="s">{{s.row.year_no}}年目</template></el-table-column><el-table-column prop="source_due_date" label="原票の提出期限" min-width="140"/><el-table-column label="計画確認日（明記分）" min-width="155"><template #default="s">{{s.row.manual_planned_date||s.row.source_planned_date||'要確認'}}</template></el-table-column><el-table-column label="完了日（原票記載）" min-width="155"><template #default="s">{{s.row.manual_completed_date||s.row.source_completed_date||'要確認'}}</template></el-table-column><el-table-column label="状態" min-width="95"><template #default="s">{{s.row.manual_status||'要確認'}}</template></el-table-column><el-table-column label="原文・補足" min-width="240"><template #default="s"><div class="preserve">{{s.row.source_text||'未記載'}}</div><div v-if="s.row.manual_notes">{{s.row.manual_notes}}</div></template></el-table-column></el-table></div></section>
<section class="panel"><header class="panel-heading">条件内容</header><div class="panel-body preserve">{{record.conditions_text||'未記載'}}</div></section>
<section class="panel"><header class="panel-heading">原資料・取込み履歴</header><div class="panel-body"><p>期限管理表 Excel {{source.sourceRow}}〜{{source.endRow}} 行</p><el-alert v-for="(w,i) in source.warnings||[]" :key="i" :title="w" type="warning" :closable="false" style="margin-bottom:8px"/><div v-for="a in data.attachments" :key="a.import_id" class="actions"><el-button link type="primary" @click="file(a)">{{a.file_name}} をダウンロード</el-button><span>{{new Date(a.created_at).toLocaleString('ja-JP')}}</span></div><el-collapse><el-collapse-item title="元セルの記載・数式・結合範囲"><el-table :data="Object.entries(source.rawCells||{}).map(([cell,value])=>({cell,value,formula:source.formulas?.[cell]}))" border><el-table-column prop="cell" label="セル" width="90"/><el-table-column label="原文"><template #default="s"><div class="preserve">{{s.row.value}}</div></template></el-table-column><el-table-column prop="formula" label="数式（計算なし）"/></el-table><p>{{(source.merges||[]).join('、')}}</p></el-collapse-item></el-collapse></div></section>
</template></div></template>
<style scoped>.preserve{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}</style>
